(2750827, 382688, 22734, '<td valign="top">Nice effect with super lighting.</td>', 'Nice effect with super lighting.', '2006-08-23 01:59:44.000000', NULL, 1),
(2750832, 382830, 22734, '<td valign="top">Makeup done to perfection. Pretty girl.</td>', 'Makeup done to perfection. Pretty girl.', '2006-08-23 02:00:57.000000', NULL, 1),
(2750847, 382971, 22734, '<td valign="top">On the money for this challenge. The penetrating gaze is quite arresting. Would have loved to see both eyes in dead on focus. Regardless, a strong and spooky image.</td>', 'On the money for this challenge. The penetrating gaze is quite arresting. Would have loved to see both eyes in dead on focus. Regardless, a strong and spooky image.', '2006-08-23 02:02:30.000000', NULL, 1),
(2750861, 382636, 22734, '<td valign="top">Convincing effect done with very good taste.</td>', 'Convincing effect done with very good taste.', '2006-08-23 02:04:27.000000', NULL, 1),
