(2753563, 382866, 40718, '<td valign="top">fun.  Nice composition.  Nice colors.  Nice lighting. 7</td>', 'fun.  Nice composition.  Nice colors.  Nice lighting. 7', '2006-08-23 17:16:45.000000', NULL, 1),
